type ctxKey struct{}

type RequestContext struct{ RequestID string; TenantID int64 }

func withRequestContext(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        rc := &RequestContext{RequestID: r.Header.Get("X-Request-Id")}
        next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), ctxKey{}, rc)))
    })
}

func handler(w http.ResponseWriter, r *http.Request) {
    rc, _ := r.Context().Value(ctxKey{}).(*RequestContext)   // typed, checked
    _ = rc.TenantID
}
